const payload = $json.body || $json;
const actionIn = (payload.action || payload.intent || 'CHECK_AVAILABILITY').toString().toUpperCase();
const action = ['CHECK_AVAILABILITY', 'BOOK_APPOINTMENT', 'RESCHEDULE_APPOINTMENT', 'CANCEL_APPOINTMENT'].includes(actionIn) ? actionIn : 'CHECK_AVAILABILITY';
const collected = payload.collected_fields || payload.collectedFields || {};

return [{
  json: {
    workflow_execution_id: $execution.id,
    action: action,
    language: ((payload.language || payload.lang || 'es').toString().toLowerCase() === 'en') ? 'en' : 'es',
    session_id: (payload.session_id || '').toString(),
    customer_id: (payload.customer_id || '').toString(),
    customer_name: (collected.name || payload.customer_name || payload.name || '').toString().trim(),
    email: (collected.email || payload.email || '').toString().trim(),
    phone: (collected.phone || payload.phone || '').toString().trim(),
    service: (collected.service || payload.service || 'general').toString().trim(),
    timezone: (collected.timezone || payload.timezone || payload.default_timezone || payload.defaultTimezone || 'America/Chicago').toString().trim(),
    date: (collected.date || payload.date || '').toString().trim(),
    start_time: (collected.start_time || payload.start_time || '').toString().trim(),
    end_time: (collected.end_time || payload.end_time || '').toString().trim(),
    appointment_id: (collected.appointment_id || payload.appointment_id || '').toString().trim(),
    channel: (payload.channel || 'web').toString(),
    intent: (payload.intent || '').toString(),
    selected_tool: (payload.selected_tool || 'CALENDAR').toString(),
    confidence: Number(payload.confidence || 0),
    maxRetries: Number(payload.max_tool_retries || payload.maxToolRetries || payload.max_retries || 1),
    retry_count: Number(payload.retry_count || 0),
    calendarConfigured: Boolean(((payload.calendar_api_url || payload.calendarApiUrl || payload.config?.calendar_api_url || '').toString().trim().length > 4) || payload.calendarConfigured || payload.calendar_configured),
    request_payload: payload
  }
}];

const p = $json;
const req = [];
if (p.action === 'CHECK_AVAILABILITY') {
  if (!p.service) req.push('service');
  if (!p.date) req.push('date');
  if (!p.timezone) req.push('timezone');
}
if (p.action === 'BOOK_APPOINTMENT') {
  if (!p.customer_name) req.push('name');
  if (!p.email) req.push('email');
  if (!p.phone) req.push('phone');
  if (!p.service) req.push('service');
  if (!p.date) req.push('date');
  if (!p.start_time) req.push('time');
  if (!p.timezone) req.push('timezone');
}
if (p.action === 'RESCHEDULE_APPOINTMENT') {
  if (!p.appointment_id) req.push('appointment_id');
  if (!p.date && !p.start_time) req.push('date_time');
  if (!p.timezone) req.push('timezone');
}
if (p.action === 'CANCEL_APPOINTMENT') {
  if (!p.appointment_id) req.push('appointment_id');
}

return [{
  json: {
    ...p,
    missing_fields: req,
    has_required_fields: req.length === 0
  }
}];

const p = $json || {};
const base = {
  workflow_execution_id: p.workflow_execution_id,
  session_id: p.session_id || '',
  customer_id: p.customer_id || '',
  customer_name: p.customer_name || '',
  email: p.email || '',
  phone: p.phone || '',
  service: p.service || 'general',
  timezone: p.timezone || 'America/Chicago',
  date: p.date || '',
  start_time: p.start_time || '',
  end_time: p.end_time || '',
  appointment_id: p.appointment_id || '',
  action: p.action,
  language: p.language || 'es',
  intent: p.intent || '',
  selected_tool: p.selected_tool || 'CALENDAR'
};

const raw = p.body || p.data || p;
const failed = p.error !== undefined || p.message || (typeof raw === 'string');
const resp = typeof raw === 'object' ? raw : {};

if (base.action === 'CHECK_AVAILABILITY') {
  const directSlots = Array.isArray(resp.available_slots) ? resp.available_slots : [];
  const candidate = Array.isArray(resp.slots) ? resp.slots : [];
  const slots = directSlots.length ? directSlots : candidate;
  const success = Array.isArray(slots) && slots.length > 0;
  return [{
    json: {
      ...base,
      found: success,
      success: success,
      status: success ? 'proposed' : 'failed',
      available_slots: success ? slots : [],
      available_days: Array.isArray(resp.available_days) ? resp.available_days : [],
      found_count: slots.length,
      message: success ? '' : (base.language === 'en' ? 'No availability found for the selected window.' : 'No hay disponibilidad para esa fecha/horario.'),
      error: success ? '' : 'no_availability'
    }
  }];
}

if (base.action === 'BOOK_APPOINTMENT') {
  const status = resp.status || (resp.confirmed === true ? 'confirmed' : '');
  const success = status === 'confirmed' || resp.success === true || resp.id;
  return [{
    json: {
      ...base,
      found: success,
      success: success,
      status: success ? 'confirmed' : 'failed',
      appointment_id: resp.appointment_id || resp.id || base.appointment_id || '',
      message: success ? '' : (base.language === 'en' ? 'Could not confirm the appointment yet.' : 'Aún no pude confirmar la cita. Verifica disponibilidad y vuelve a intentar.'),
      error: success ? '' : 'calendar_create_failed'
    }
  }];
}

if (base.action === 'RESCHEDULE_APPOINTMENT') {
  const status = resp.status || (resp.success === true ? 'rescheduled' : '');
  const success = status === 'rescheduled';
  return [{
    json: {
      ...base,
      found: success,
      success: success,
      status: success ? 'rescheduled' : 'failed',
      appointment_id: resp.appointment_id || resp.id || base.appointment_id || '',
      message: success ? '' : (base.language === 'en' ? 'Could not reschedule the appointment.' : 'No pude reprogramar la cita con los datos recibidos.'),
      error: success ? '' : 'calendar_reschedule_failed'
    }
  }];
}

if (base.action === 'CANCEL_APPOINTMENT') {
  const status = resp.status || (resp.success === true ? 'cancelled' : '');
  const success = status === 'cancelled';
  return [{
    json: {
      ...base,
      found: success,
      success: success,
      status: success ? 'cancelled' : 'failed',
      appointment_id: resp.appointment_id || resp.id || base.appointment_id || '',
      message: success ? '' : (base.language === 'en' ? 'Could not cancel the appointment.' : 'No pude cancelar la cita con la información disponible.'),
      error: success ? '' : 'calendar_cancel_failed'
    }
  }];
}

return [{
  json: {
    ...base,
    found: false,
    success: false,
    status: 'failed',
    message: base.language === 'en' ? 'Unsupported appointment action.' : 'Acción de cita no soportada.',
    error: 'unsupported_action'
  }
}];
